import{c as n,$ as a,Q as t,j as i,m as o,h as l,ax as r,n as h,o as c,S as d}from"./chunks/framework.BqPkuuVc.js";const T=JSON.parse('{"title":"HTTPS and certificates","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/https-and-certificates.md","filePath":"user/reference/https-and-certificates.md"}'),g={name:"user/reference/https-and-certificates.md"};function u(p,e,m,f,w,y){const s=a("Mermaid");return t(),i("div",null,[e[1]||(e[1]=o('<h1 id="https-and-certificates" tabindex="-1">HTTPS and certificates <a class="header-anchor" href="#https-and-certificates" aria-label="Permalink to &quot;HTTPS and certificates&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and timing operators who download SportIdent cards or back up stations from a computer <strong>other than</strong> the server.</p><p>meshO Manager runs fine over plain <code>http://</code> for almost everything. The exceptions are the features that talk to USB hardware <strong>in the browser</strong>: reading a SportIdent USB reader station (BSM7-USB / BSM8-USB) uses the Web Serial API, and printing splits to a USB thermal printer plugged into a download station uses the WebUSB API (see <a href="./settings">Settings → Splits Printer</a>). Browsers only allow <em>both</em> on a <strong>secure connection</strong>. On the server computer itself that&#39;s free (<code>localhost</code> always counts as secure); on any <em>other</em> computer it means turning on HTTPS and trusting meshO&#39;s certificate once.</p><p>This page explains when you need HTTPS, how to switch it on, how meshO&#39;s certificate works, how to trust it on each device, and — importantly — exactly what happens if you don&#39;t.</p><h2 id="do-you-even-need-https" tabindex="-1">Do you even need HTTPS? <a class="header-anchor" href="#do-you-even-need-https" aria-label="Permalink to &quot;Do you even need HTTPS?&quot;">​</a></h2><p>Most events don&#39;t. Work through this first:</p><table tabindex="0"><thead><tr><th>Your situation</th><th>What to do</th></tr></thead><tbody><tr><td>You download cards <strong>on the same computer that runs the server</strong></td><td><strong>You don&#39;t need HTTPS.</strong> Just open Manager at <code>http://localhost:5154/manager</code>. <code>localhost</code> is always a secure context, so Web Serial works.</td></tr><tr><td>You only use Manager to view results, register competitors, run leaderboards, or watch radio punches on other devices</td><td><strong>You don&#39;t need HTTPS.</strong> None of those use Web Serial. Plain HTTP over the LAN is fine.</td></tr><tr><td>You download cards or back up stations <strong>on a different computer</strong> to the server (a separate download laptop)</td><td><strong>You need HTTPS</strong> on the server, and the certificate trusted on that download laptop. Read on.</td></tr><tr><td>You print splits to a USB thermal printer plugged into a <strong>different computer</strong> to the server (a download laptop with its own printer)</td><td><strong>You need HTTPS</strong>, same as card download — WebUSB has the identical secure-context rule. Read on.</td></tr></tbody></table><blockquote><p><strong>Why the restriction?</strong> The Web Serial and WebUSB APIs talk directly to USB hardware from inside the browser. Browsers only expose them on <code>localhost</code> or over <code>https://</code>. That&#39;s a browser security rule, not a meshO choice — there&#39;s no setting that turns it off. See <a href="./../running-the-event/card-download">Downloading cards</a>.</p></blockquote><blockquote><p><strong>Which browsers have which API?</strong> Card download and station backup use <strong>Web Serial</strong> — Chrome, Edge and Firefox 151+. Printing to a USB thermal printer uses <strong>WebUSB</strong>, which is Chrome and Edge only; Firefox doesn&#39;t implement it. So a Firefox download laptop can read cards but can&#39;t drive its own thermal printer.</p></blockquote><blockquote><p><strong>On the server, use <code>localhost</code> specifically — not its host name or IP.</strong> Only <code>localhost</code> (and <code>127.0.0.1</code>) counts as a secure context over plain HTTP. If you reach the <em>same</em> machine through its own host name or LAN IP — say <code>http://192.168.1.42:5154/manager</code> — the browser treats it as an ordinary insecure origin and <strong>withholds Web Serial</strong>, so the download affordance won&#39;t appear even though you&#39;re sitting at the server. Open <code>http://localhost:5154/manager</code> (the address the tray / menu bar app uses) and it just works, no HTTPS needed.</p></blockquote><h2 id="turn-on-https" tabindex="-1">Turn on HTTPS <a class="header-anchor" href="#turn-on-https" aria-label="Permalink to &quot;Turn on HTTPS&quot;">​</a></h2><ol><li>On the <strong>server</strong> computer, open <strong>Settings → Server</strong>.</li><li>Switch on <strong>Enable HTTPS (for download / station-backup machines)</strong>.</li><li>Leave the <strong>HTTPS Port</strong> at the default (<code>5155</code>) unless it clashes with something else on the machine. It must be different from the HTTP port.</li><li>Save your settings.</li><li><strong>Restart the server</strong> — HTTPS only binds at startup. On the server you can do this from the tray / menu bar icon: <strong>Restart Server</strong>.</li></ol><p>After the restart, <strong>Settings → Server</strong> shows a table of <strong>Access links</strong>. The secure ones are tagged <strong>HTTPS</strong>. These are the links your download laptop should use.</p><blockquote><p><strong>HTTP never goes away.</strong> Turning on HTTPS <em>adds</em> a secure endpoint alongside the existing plain-HTTP one. Everything that already worked over HTTP — the tray app opening <code>localhost</code>, leaderboard TVs, spectator phones, registration laptops — keeps working exactly as before. If HTTPS can&#39;t start for any reason (see <a href="#troubleshooting">Troubleshooting</a>), Manager quietly falls back to HTTP-only rather than failing to start.</p></blockquote><h2 id="how-mesho-s-certificate-works" tabindex="-1">How meshO&#39;s certificate works <a class="header-anchor" href="#how-mesho-s-certificate-works" aria-label="Permalink to &quot;How meshO&#39;s certificate works&quot;">​</a></h2><p>A secure (<code>https://</code>) connection needs a <strong>certificate</strong>. Public websites buy one from an authority your browser already trusts. meshO can&#39;t do that — it runs on your laptop on a private network with no public name — so instead it acts as its own small <strong>certificate authority (CA)</strong>:</p>',16)),(t(),l(d,null,{default:r(()=>[c(s,{id:"mermaid-123",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20ca(%5B%22meshO%20Manager%20Local%20CA%22%5D)%0A%20%20%20%20leaf(%5B%22Server%20certificate%22%5D)%0A%20%20%20%20ca%20--%3E%7Csigns%7C%20leaf%0A%20%20%20%20leaf%20--%3E%20https%5B%22enables%20https%3A%2F%2F%20links%22%5D%0A%20%20%20%20style%20ca%20fill%3A%23FF914D%2Ccolor%3A%23000000%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o(`<ul><li>The <strong>CA</strong> is created automatically the first time HTTPS is enabled and is reused from then on.</li><li>It signs a short-lived <strong>server certificate</strong> for this computer&#39;s current name and LAN IP. If you rename the computer or it moves to a different network, that server certificate has to change — meshO handles this for you (see <a href="#if-the-server-is-renamed-or-its-ip-changes">If the server is renamed or its IP changes</a>).</li><li>A device trusts <strong>the CA once</strong>, and then every certificate the CA signs is trusted too. That&#39;s why you install the CA, not the per-machine certificate.</li></ul><p>The certificate files live in your meshO data folder under <code>certs/</code>. The private keys never leave the server.</p><h2 id="if-the-server-is-renamed-or-its-ip-changes" tabindex="-1">If the server is renamed or its IP changes <a class="header-anchor" href="#if-the-server-is-renamed-or-its-ip-changes" aria-label="Permalink to &quot;If the server is renamed or its IP changes&quot;">​</a></h2><p>The per-machine server certificate is tied to the server&#39;s <strong>name</strong> and <strong>LAN IP</strong>, so if either of those changes the certificate must be updated. The important thing to know:</p><blockquote><p><strong>A rename or new IP does <em>not</em> mean reinstalling certificates on anyone&#39;s device.</strong></p><ul><li><strong>It&#39;s automatic.</strong> meshO notices the new name/IP and reissues the server certificate itself. You never create, request, or copy a certificate by hand.</li><li><strong>Restart the server to apply it.</strong> HTTPS binds its certificate when the server starts, so restart the server (tray / menu bar → <strong>Restart Server</strong>) for the new certificate to be served. Until you restart, the old certificate is still in use, so connecting by the <em>new</em> name will show a name-mismatch warning.</li><li><strong>No reinstalling — on the server <em>or</em> the clients.</strong> The reissued certificate is signed by the <strong>same</strong> long-lived meshO CA your devices already trust, so that trust carries straight over. You install the CA <strong>once per device</strong> and never again, even after a rename or network change.</li></ul><p>The only thing to get right afterwards is that each device reaches the server by a name or IP the new certificate covers — the current computer name, its <code>.local</code> name, and the LAN IP, all listed in the <strong>Access links</strong> table in <strong>Settings → Server</strong>. If anyone bookmarked the <em>old</em> address, update the bookmark.</p></blockquote><p>The single exception is the rare case where meshO has to regenerate the <strong>CA itself</strong> (for example, the CA expired after ten years, or its file was corrupted). That <em>does</em> require re-trusting the new CA on every device — but it doesn&#39;t happen on an ordinary rename or IP change.</p><h2 id="trusting-the-certificate" tabindex="-1">Trusting the certificate <a class="header-anchor" href="#trusting-the-certificate" aria-label="Permalink to &quot;Trusting the certificate&quot;">​</a></h2><p>&quot;Trusting&quot; is the step that tells a device&#39;s browser the meshO CA is legitimate. <strong>It&#39;s separate from turning HTTPS on</strong> — HTTPS serves whether or not anything trusts it; trusting is what makes the browser warning go away.</p><p>You trust the CA <strong>once per device</strong> that will open a secure link.</p><h3 id="on-the-server-computer" tabindex="-1">On the server computer <a class="header-anchor" href="#on-the-server-computer" aria-label="Permalink to &quot;On the server computer&quot;">​</a></h3><p>In <strong>Settings → Server</strong>, under <strong>Trust the certificate</strong>, click <strong>Install certificate on the server</strong>. What this does depends on the operating system:</p><ul><li><strong>Windows</strong> — adds the CA to your user&#39;s trust store directly. You&#39;ll get a one-time Windows consent prompt; click <strong>Yes</strong>.</li><li><strong>macOS</strong> — adds the CA to your login keychain. macOS may ask for your keychain or login password.</li><li><strong>Linux</strong> — system trust usually needs root, so the automatic button often <em>can&#39;t</em> do it. Use the manual steps below.</li></ul><p>When it works, the button is replaced by a green <strong>Trusted on the server</strong> chip. If it didn&#39;t take, you&#39;ll see a <strong>Not trusted yet</strong> chip and a message explaining why — fall back to the manual steps under <strong>&quot;The button didn&#39;t work?&quot;</strong> on that screen, or <a href="#installing-manually">below</a>.</p><h3 id="on-other-machines-download-backup-laptops" tabindex="-1">On other machines (download / backup laptops) <a class="header-anchor" href="#on-other-machines-download-backup-laptops" aria-label="Permalink to &quot;On other machines (download / backup laptops)&quot;">​</a></h3><p>These are always done by hand, because meshO can only automate trust on the machine it&#39;s running on.</p><ol><li><strong>On that laptop</strong>, open Manager over the LAN — use the <strong>IP</strong> link, e.g. <code>http://&lt;server-ip&gt;:5154/manager</code>. A download laptop usually runs Chrome, and Chrome often can&#39;t resolve the server&#39;s name; see <a href="./server-addresses">Reaching the server: name or IP</a>.</li><li>Go to <strong>Settings → Server</strong> and click <strong>Download certificate</strong> (or browse directly to <code>http://&lt;server-ip&gt;:5154/manager/api/https/ca.crt</code>).</li><li>Install the downloaded file following the steps for that device&#39;s operating system, <a href="#installing-manually">below</a>.</li><li>Re-open the laptop using the <strong>HTTPS</strong> access link. The warning should be gone and card download will work.</li></ol><h2 id="installing-manually" tabindex="-1">Installing manually <a class="header-anchor" href="#installing-manually" aria-label="Permalink to &quot;Installing manually&quot;">​</a></h2><p>The downloaded file is named <code>meshO-CA-&lt;computer&gt;.crt</code>. Install it as a <strong>trusted root certificate authority</strong>:</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>Double-click the <code>.crt</code> file → <strong>Install Certificate</strong>.</li><li>Choose <strong>Current User</strong> → <strong>Next</strong>.</li><li>Select <strong>Place all certificates in the following store</strong> → <strong>Browse</strong> → <strong>Trusted Root Certification Authorities</strong> → <strong>OK</strong>.</li><li><strong>Next</strong> → <strong>Finish</strong>. Confirm the security prompt with <strong>Yes</strong>.</li><li>Fully close and reopen the browser.</li></ol><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><ol><li>Double-click the <code>.crt</code> to open it in <strong>Keychain Access</strong> (it lands in the <strong>login</strong> keychain).</li><li>Find <strong>meshO Manager Local CA</strong>, double-click it, and expand the <strong>Trust</strong> section.</li><li>Set <strong>When using this certificate</strong> to <strong>Always Trust</strong>.</li><li>Close the window — macOS will ask for your password to save the change.</li></ol><h3 id="ipad-iphone-ios-ipados" tabindex="-1">iPad / iPhone (iOS / iPadOS) <a class="header-anchor" href="#ipad-iphone-ios-ipados" aria-label="Permalink to &quot;iPad / iPhone (iOS / iPadOS)&quot;">​</a></h3><p>Apple splits this into <em>install</em> and <em>trust</em>:</p><ol><li>Open the download link in <strong>Safari</strong> (other browsers won&#39;t trigger the profile install). Tap <strong>Allow</strong> when asked to download a configuration profile.</li><li>Go to <strong>Settings → General → VPN &amp; Device Management</strong>, tap the downloaded <strong>meshO</strong> profile, and tap <strong>Install</strong> (enter your passcode).</li><li>Then go to <strong>Settings → General → About → Certificate Trust Settings</strong> and switch <strong>on</strong> the meshO CA under <em>Enable full trust for root certificates</em>. <strong>This second step is essential</strong> — without it the certificate is installed but not trusted.</li></ol><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h3><ol><li>Open <strong>Settings</strong> and search for <strong>Install a certificate</strong>, or go to <strong>Security → Encryption &amp; credentials → Install a certificate → CA certificate</strong>.</li><li>Pick the downloaded <code>meshO-CA-*.crt</code> file and confirm.</li></ol><blockquote><p>Some Android builds and some browsers (notably Chrome on certain versions) only honour user-installed CAs in limited ways. If a secure link still warns after installing, prefer running the download station on a Windows or Mac laptop.</p></blockquote><h3 id="linux-system-chrome-chromium" tabindex="-1">Linux (system + Chrome/Chromium) <a class="header-anchor" href="#linux-system-chrome-chromium" aria-label="Permalink to &quot;Linux (system + Chrome/Chromium)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meshO-CA-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.crt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/share/ca-certificates/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-ca-certificates</span></span></code></pre></div><p>Chrome and Chromium keep their <strong>own</strong> certificate store separate from the system one. Add it there too: <strong>⋮ → Settings → Privacy and security → Security → Manage certificates → Authorities → Import</strong>, then tick <em>&quot;Trust this certificate for identifying websites.&quot;</em></p><h2 id="what-happens-if-you-don-t-trust-the-certificate" tabindex="-1">What happens if you <em>don&#39;t</em> trust the certificate <a class="header-anchor" href="#what-happens-if-you-don-t-trust-the-certificate" aria-label="Permalink to &quot;What happens if you *don&#39;t* trust the certificate&quot;">​</a></h2><p>Nothing breaks, and nothing is at risk — but the experience degrades. Specifically:</p><ul><li><strong>The server still starts and HTTPS still runs.</strong> Trusting the CA is not required for the secure endpoint to come up. Manager keeps serving both HTTP and HTTPS.</li><li><strong>HTTP keeps working everywhere.</strong> The tray app, leaderboard TVs, registration laptops, spectator phones — all unaffected.</li><li><strong>Secure links show a browser warning.</strong> Opening an <strong>HTTPS</strong> access link on a device that hasn&#39;t trusted the CA produces <em>&quot;Your connection is not private&quot;</em> (Chrome: <code>NET::ERR_CERT_AUTHORITY_INVALID</code>; Edge similar). You can usually click <strong>Advanced → Proceed</strong> to continue.</li><li><strong>Card download may be blocked.</strong> This is the one that actually bites: on an untrusted secure origin, some browsers withhold the Web Serial API, so the <strong>Connect</strong>/download affordance won&#39;t appear even after you click past the warning. Trusting the certificate is what reliably enables it.</li><li><strong>The Settings screen tells you.</strong> Under <strong>Trust the certificate</strong> you&#39;ll see a <strong>Not trusted yet</strong> chip and a yellow note explaining the above, instead of the green <strong>Trusted on the server</strong> chip.</li></ul><blockquote><p><strong>The simplest workaround of all:</strong> if the computer doing the downloading <em>is</em> the server, don&#39;t bother with any of this — open Manager at <code>http://localhost:5154/manager</code>. <code>localhost</code> is automatically a secure context, so Web Serial works with no certificate and no warning. HTTPS only matters for download/backup stations on a <strong>separate</strong> computer.</p></blockquote><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>HTTPS is enabled but the access table shows no secure links / a warning banner.</strong> HTTPS is enabled in settings but didn&#39;t bind at startup. The banner gives the reason. Common causes:</p><ul><li><em>The HTTPS port equals the HTTP port.</em> They must differ — change <strong>HTTPS Port</strong> (default <code>5155</code>).</li><li><em>The HTTPS port is already in use</em> by another program. Pick a free port and restart.</li><li><em>The certificate couldn&#39;t be prepared.</em> Rare; see the server log. Manager degrades to HTTP-only so the rest of the event is unaffected.</li></ul><p>Remember a setting change only takes effect after a <strong>server restart</strong>.</p><p><strong>I trusted it, but the browser still warns.</strong></p><ul><li>Make sure you trusted it <strong>on the device showing the warning</strong>, not just the server.</li><li>Fully <strong>quit and reopen</strong> the browser — certificate stores are read at startup.</li><li>Check you opened the link by the <strong>same name</strong> the certificate was issued for. If you trusted via <code>mesho.local</code> but open by raw IP (or vice-versa), and the certificate only covers one of them, you&#39;ll still get a name-mismatch warning. The access table lists both name and IP variants.</li><li>On iОS, confirm you completed the <strong>second</strong> step (Certificate Trust Settings), not just the profile install.</li></ul><p><strong>I renamed the computer / changed networks and now it warns again.</strong> meshO reissues the server certificate automatically for the new name/IP, signed by the <strong>same</strong> CA — so devices that already trust the CA keep working, with <strong>no reinstall needed</strong>. Two things to check: (1) <strong>restart the server</strong> so the new certificate is actually served (it binds at startup), and (2) make sure you&#39;re reaching the machine by a name/IP the new certificate covers. If a device still warns after that, it most likely never trusted the CA in the first place. See <a href="#if-the-server-is-renamed-or-its-ip-changes">If the server is renamed or its IP changes</a> for the full explanation.</p><p><strong>Can I avoid certificates entirely?</strong> Yes — run the download station on the <strong>server computer</strong> and use <code>http://localhost:5154/manager</code>. That&#39;s the recommended setup for small events.</p><h2 id="security-notes" tabindex="-1">Security notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security notes&quot;">​</a></h2><ul><li>The meshO CA is generated <strong>locally</strong> and its private key never leaves the server. It can only vouch for meshO&#39;s own certificates on your machines.</li><li>Trust is installed in the <strong>current user&#39;s</strong> store, not system-wide where avoidable, keeping the footprint small.</li><li>The per-machine server certificate is <strong>short-lived</strong> and reissued as needed, so a leaked key has a limited lifetime.</li><li>Trusting the meshO CA does <strong>not</strong> let meshO (or anyone else) intercept your other browsing — a privately-generated CA can only sign certificates meshO holds the keys for, and it lives only on the devices you chose to install it on. Remove it any time from the same trust store you added it to.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../running-the-event/card-download">Downloading cards</a> — the Web Serial download flow that HTTPS exists to support.</li><li><a href="./server-addresses">Reaching the server: name or IP</a> — which of the access links a download laptop should use, and why it&#39;s usually the IP one.</li><li><a href="./sportident-usb-on-macos">SportIdent USB stations on macOS</a> — the <em>other</em> reason a Mac may not offer the station: the CP210x driver isn&#39;t installed, so no serial port exists to choose.</li><li><a href="./../download-and-install/">Download, install and update</a> — installing the server and opening Manager on other devices.</li><li><a href="./multi-operator-setup">Multi-operator setup</a> — network and workstation setup for a multi-person event.</li><li><a href="./settings">Settings</a> — the <strong>Server</strong> section where HTTPS, ports, and LAN access live.</li><li><a href="./troubleshooting">Troubleshooting</a> — general &quot;it won&#39;t start / won&#39;t connect&quot; help.</li></ul>`,47))])}const v=n(g,[["render",u]]);export{T as __pageData,v as default};
